/* Native SVG statistics and a market workspace. No external chart library. */
let marketData=null,marketBusy=false,marketError='',marketSelected='',marketFilter='all',marketAttempted=false,marketGeneration=0;
const mcEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mcNumber(value){if(value===null||value===undefined||value===''||typeof value==='boolean')return null;if(typeof value==='string'&&!/^[+-]?\d+(?:\.\d+)?$/.test(value))return null;const n=Number(value);return Number.isFinite(n)&&Math.abs(n)<=1e12?n:null}
function mcFormat(value,digits=2){const n=mcNumber(value);return n===null?'—':n.toLocaleString('en-US',{maximumFractionDigits:digits,minimumFractionDigits:Number.isInteger(n)?0:Math.min(2,digits)})}
function mcSigned(value,suffix=''){const n=mcNumber(value);return n===null?'—':(n>0?'+':'')+mcFormat(n)+suffix}
const mcPalette=['#2454bc','#ffd02f','#d83c30','#20201c','#50835a','#9566b8','#d78735','#668c98'];
function mcEmpty(title,detail){return `<div class="mc-empty"><strong>${mcEscape(title)}</strong><p>${mcEscape(detail)}</p></div>`}
function mcTable(headers,rows,caption){return `<div class="mc-table"><table><caption>${mcEscape(caption)}</caption><thead><tr>${headers.map(h=>`<th scope="col">${mcEscape(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>`<${i===0?'th scope="row"':'td'}>${mcEscape(cell)}</${i===0?'th':'td'}>`).join('')}</tr>`).join('')||`<tr><td colspan="${headers.length}">尚無可顯示資料</td></tr>`}</tbody></table></div>`}
function mcDisclosure(table,label='查看完整數據表'){return `<details class="mc-data"><summary>${mcEscape(label)}</summary>${table}</details>`}
function allocationDonut(rows,total,currency='TWD'){
 const full=Array.isArray(rows)?rows.map(r=>({name:String(r.asset_class||r.name||'未命名'),value:mcNumber(r.value)})):[],knownTotal=mcNumber(total);
 const table=mcTable(['資產類別',`金額 / ${currency}`,'占總資產'],full.map(r=>[r.name,mcFormat(r.value),knownTotal>0&&r.value!==null?(r.value/knownTotal*100).toFixed(2)+'%':'—']),'資產配置原始數據');
 if(!full.length||knownTotal===null||knownTotal<=0)return mcEmpty('目前還不能畫比例圖。','需要大於零的總資產與有效配置資料，沒有數據時不補上假比例。')+mcDisclosure(table);
 if(full.some(r=>r.value===null||r.value<0))return mcEmpty('這份配置包含負值或無效金額。','負數資產不適合圓餅或環形比例圖；請先核對帳戶與持倉，以下保留原始數值。')+mcDisclosure(table);
 const sum=full.reduce((s,r)=>s+Math.round(r.value*100),0)/100;
 if(Math.abs(sum-knownTotal)>.011)return mcEmpty('分類合計與總資產不一致。','比例圖暫不顯示，避免把不完整的配置畫成100%；請先核對數據。')+mcDisclosure(table);
 const positive=full.filter(r=>r.value>0),radius=64,length=2*Math.PI*radius;let offset=0;
 const segments=positive.map((r,i)=>{const arc=r.value/knownTotal*length,part=`<circle cx="104" cy="104" r="${radius}" fill="none" stroke="${mcPalette[i%mcPalette.length]}" stroke-width="27" stroke-dasharray="${arc.toFixed(6)} ${(length-arc).toFixed(6)}" stroke-dashoffset="${(-offset).toFixed(6)}" transform="rotate(-90 104 104)"><title>${mcEscape(r.name)}：${mcFormat(r.value)} ${mcEscape(currency)}，${(r.value/knownTotal*100).toFixed(2)}%</title></circle>`;offset+=arc;return part}).join('');
 return `<figure class="mc-figure"><figcaption class="mc-sr">有效資產配置，總額 ${mcFormat(knownTotal)} ${mcEscape(currency)}。完整金額可展開數據表。</figcaption><div class="mc-donut-layout"><svg class="mc-donut" viewBox="0 0 208 208" role="img" aria-label="資產配置環形圖，總額${mcFormat(knownTotal)} ${mcEscape(currency)}"><title>非負資產配置；金額依實際資料計算</title>${segments}<text x="104" y="99" text-anchor="middle" class="mc-svg-number">100%</text><text x="104" y="121" text-anchor="middle" class="mc-svg-label">${mcEscape(currency)}</text></svg><ul class="mc-legend">${positive.map((r,i)=>`<li><i style="background:${mcPalette[i%mcPalette.length]}" aria-hidden="true"></i><span>${mcEscape(r.name)}</span><strong>${(r.value/knownTotal*100).toFixed(1)}%</strong></li>`).join('')}</ul></div>${mcDisclosure(table)}</figure>`;
}
function signedHorizontalChart(rows,{unit='TWD',title='分類淨支出',caption='正數為淨支出，負數為退款或更正。',className=''}={}){
 const data=(Array.isArray(rows)?rows:[]).map(r=>({label:String(r.label||r.name||'未命名'),value:mcNumber(r.value)})).filter(r=>r.value!==null),table=mcTable(['項目',unit],data.map(r=>[r.label,mcSigned(r.value)]),title+'原始數據');
 if(!data.length)return mcEmpty('尚無可繪製資料。','無效或缺少的數值不會當成零。')+mcDisclosure(table);
 const width=640,left=185,right=65,plotWidth=width-left-right,zero=left+plotWidth/2,half=plotWidth/2,max=Math.max(1,...data.map(r=>Math.abs(r.value))),height=48+data.length*39;
 const bars=data.map((r,i)=>{const y=22+i*39,extent=Math.abs(r.value)/max*half,x=r.value<0?zero-extent:zero,tip=`${r.label}：${mcSigned(r.value)} ${unit}`;return `<text x="${left-12}" y="${y+16}" text-anchor="end" class="mc-svg-label">${mcEscape(r.label.length>16?r.label.slice(0,15)+'…':r.label)}</text><rect x="${x.toFixed(2)}" y="${y}" width="${extent.toFixed(2)}" height="23" rx="3" class="${r.value<0?'mc-negative':'mc-positive'}" data-chart-tip="${mcEscape(tip)}" tabindex="0" role="img" aria-label="${mcEscape(tip)}"><title>${mcEscape(tip)}</title></rect><text x="${r.value<0?x-7:x+extent+7}" y="${y+16}" text-anchor="${r.value<0?'end':'start'}" class="mc-svg-label">${mcEscape(mcSigned(r.value))}</text>`}).join('');
 return `<figure class="mc-figure ${mcEscape(className)}"><figcaption>${mcEscape(caption)}</figcaption><div class="mc-tooltip" role="status" aria-live="polite">移到長條上，或用 Tab 聚焦查看數值。</div><div class="mc-svg-scroll" tabindex="0" aria-label="${mcEscape(title)}圖表，可橫向捲動"><svg viewBox="0 0 ${width} ${height}" role="group" aria-label="${mcEscape(title)}；以零為中心，單位${mcEscape(unit)}"><title>${mcEscape(title)}</title><line x1="${zero}" y1="10" x2="${zero}" y2="${height-20}" class="mc-axis"/>${bars}<text x="${zero}" y="${height-3}" text-anchor="middle" class="mc-svg-label">0</text><text x="${width-4}" y="${height-3}" text-anchor="end" class="mc-svg-label">${mcEscape(unit)}</text></svg></div>${mcDisclosure(table)}</figure>`;
}
function financialCashflowChart(history){
 const rows=(Array.isArray(history)?history:[]).filter(r=>/^\d{4}-(0[1-9]|1[0-2])$/.test(String(r.month))&&mcNumber(r.income)!==null&&mcNumber(r.expense)!==null).map(r=>({month:r.month,income:mcNumber(r.income),expense:mcNumber(r.expense)})).slice(-12);
 if(!rows.length)return mcEmpty('尚無月份收支資料。','圖表只使用已有的月份統計，不會補出不存在的收入或支出。');
 const table=mcTable(['月份','收入 / TWD','支出 / TWD'],rows.map(r=>[r.month,mcFormat(r.income),mcFormat(r.expense)]),'月份收支原始數據'),w=640,h=258,left=65,right=20,top=25,bottom=43,min=Math.min(0,...rows.flatMap(r=>[r.income,r.expense])),max=Math.max(1,...rows.flatMap(r=>[r.income,r.expense])),span=max-min,y=n=>top+(max-n)/span*(h-top-bottom),zero=y(0),step=(w-left-right)/rows.length,bw=Math.min(23,step*.28);
 const ticks=Array.from({length:5},(_,i)=>min+span*i/4).map(v=>`<line x1="${left}" x2="${w-right}" y1="${y(v).toFixed(2)}" y2="${y(v).toFixed(2)}" class="mc-grid"/><text x="${left-8}" y="${(y(v)+4).toFixed(2)}" text-anchor="end" class="mc-svg-label">${mcEscape(mcFormat(v,0))}</text>`).join('');
 const bars=rows.map((r,i)=>{const x=left+step*i+step/2;return ['income','expense'].map((kind,j)=>{const v=r[kind],tip=`${r.month} ${kind==='income'?'收入':'支出'} ${mcFormat(v)} TWD`;return `<rect x="${(x+(j===0?-bw-2:2)).toFixed(2)}" y="${Math.min(zero,y(v)).toFixed(2)}" width="${bw}" height="${Math.abs(y(v)-zero).toFixed(2)}" rx="2" class="${kind==='income'?'mc-positive':'mc-expense'}" tabindex="0" data-chart-tip="${mcEscape(tip)}" role="img" aria-label="${mcEscape(tip)}"><title>${mcEscape(tip)}</title></rect>`}).join('')+`<text x="${x.toFixed(2)}" y="${h-19}" text-anchor="middle" class="mc-svg-label">${r.month.slice(2)}</text>`}).join('');
 return `<figure class="mc-figure"><figcaption>月份收入與支出，保留負數更正；單位 TWD。</figcaption><div class="mc-tooltip" role="status" aria-live="polite">藍色為收入，黃色為支出。滑過長條查看數字。</div><div class="mc-svg-scroll" tabindex="0" aria-label="月份收支圖可橫向捲動"><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="月份收支柱狀圖，含零基線與帶正負值的數據表"><title>月份收支 / TWD</title>${ticks}<line x1="${left}" x2="${w-right}" y1="${zero.toFixed(2)}" y2="${zero.toFixed(2)}" class="mc-axis"/>${bars}<text x="${left}" y="14" class="mc-svg-label">TWD</text></svg></div>${mcDisclosure(table)}</figure>`;
}
function dashboardFinancialCharts(){return `<section class="mc-dashboard-charts" aria-label="財務統計圖表"><div class="mc-section-heading"><div><span class="ws-kicker">FINANCIAL STATISTICS</span><h2>把數字，放進同一張圖。</h2></div><span class="mc-source-label">${typeof demoMode!=='undefined'&&demoMode?'合成財務資料':'已確認財務資料'} / TWD</span></div><div class="mc-stat-grid"><section class="ws-card"><h3>資產配置</h3>${allocationDonut(ws.allocation,ws.assets)}</section><section class="ws-card"><h3>本月分類淨支出</h3>${signedHorizontalChart(Object.entries(ws.spending||{}).map(([label,value])=>({label,value})))}</section></div><section class="ws-card"><h3>月份現金流</h3>${financialCashflowChart(flowData.history)}</section></section>`}
function marketSyntheticData(){
 const dates=['2026-10-19','2026-10-20','2026-10-21','2026-10-22','2026-10-23','2026-10-26','2026-10-27','2026-10-28','2026-10-29','2026-10-30'];
 const specs=[['demo-tw-index','合成台股大盤','index','TW','示例大盤','TWD','index_points',[22000,22120,22030,22240,22180,22310,22420,22360,22510,22600]],['demo-tw-etf','合成台股 ETF','etf','TW','示例ETF','TWD','price',[52,52.2,51.8,52.5,52.4,52.8,53.1,52.9,53.2,53.5]],['demo-us-index','合成美股大盤','index','US','示例大盤','USD','index_points',[5600,5620,5608,5640,5635,5660,5652,5680,5673,5690]],['demo-chip-stock','合成半導體標的','stock','TW','示例晶片','TWD','price',[900,915,908,923,919,930,942,936,945,955]],['demo-tech-stock','合成科技標的','stock','US','示例科技','USD','price',[190,192,191,193,191,190,189,190,188,187]]];
 return {demo:true,as_of:'2026-10-30',quotes:specs.map(([id,label,kind,market,symbol,currency,unit,prices])=>({id,label,kind,market,symbol,currency,unit,status:'demo',price:String(prices.at(-1)),change:String(prices.at(-1)-prices.at(-2)),change_percent:String((prices.at(-1)/prices.at(-2)-1)*100),as_of:'2026-10-30',source:'固定合成資料，非真實市場',delay:'僅供圖表體驗',stale:false,closed:true,error:null,history:dates.map((date,i)=>({date,close:String(prices[i])})),sector:id==='demo-chip-stock'?'半導體':id==='demo-tech-stock'?'科技':'未分類'})),providers:{mode:'synthetic'}};
}
function marketErrorText(error){return !error?'':typeof error==='object'?String(error.message||error.code||'來源資料未完整取得'):String(error)}
function marketStatus(q){if(q.status==='demo')return '合成示例';if(q.status==='missing_key')return '尚未設定服務 Key';if(q.status==='permission_denied')return '來源未授權';if(q.status==='quota_deferred')return '本輪額度已滿，稍後更新';if(q.status==='rate_limited')return '來源速率限制';if(q.error)return '資料未完整取得';if(mcNumber(q.price)===null)return '尚無報價';if(q.stale)return '較舊資料';if(q.closed)return '已收盤';return q.status==='ok'?'已取得資料':String(q.status||'資料狀態未提供')}
function marketQuotes(){return Array.isArray(marketData?.quotes)?marketData.quotes.filter(q=>q&&typeof q==='object').slice(0,200):[]}
function marketVisibleQuotes(){return marketQuotes().filter(q=>marketFilter==='all'||marketFilter==='TW'&&q.market==='TW'||marketFilter==='US'&&q.market==='US'||marketFilter==='etf'&&q.kind==='etf'||marketFilter==='index'&&q.kind==='index'||marketFilter==='stock'&&q.kind==='stock')}
function marketPoints(q){const seen=new Map();for(const r of Array.isArray(q?.history)?q.history:[]){if(!r||typeof r!=='object')continue;const date=String(r.date||r.day||'').slice(0,10),n=mcNumber(r.close??r.price??r.value);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||isNaN(Date.parse(date))||new Date(date+'T12:00:00Z').toISOString().slice(0,10)!==date||n===null||n<0)continue;seen.set(date,{date,value:n})}return [...seen.values()].sort((a,b)=>a.date.localeCompare(b.date)).slice(-260)}
function marketPriceChart(q){
 if(!q)return mcEmpty('先選擇一個標的。','有可核對的日期與收盤值後，才會顯示走勢。');
 const points=marketPoints(q),unit=q.unit==='index_points'?'指數點位':String(q.currency||'幣別未提供'),table=mcTable(['日期',q.unit==='index_points'?'收盤指數 / 點':`收盤價 / ${unit}`],points.map(p=>[p.date,mcFormat(p.value)]),String(q.label||q.symbol)+'歷史資料');
 if(points.length<2)return mcEmpty('歷史資料不足兩個日期。','不補造走勢或用單一報價推算曲線。以下保留已取得的日期與數字。')+mcDisclosure(table);
 const w=640,h=275,left=76,right=25,top=29,bottom=48,start=Date.parse(points[0].date),end=Date.parse(points.at(-1).date),low=Math.min(...points.map(p=>p.value)),high=Math.max(...points.map(p=>p.value)),pad=Math.max((high-low)*.12,Math.abs(high)*.005,.01),min=Math.max(0,low-pad),max=high+pad,x=date=>left+(Date.parse(date)-start)/(end-start)*(w-left-right),y=value=>top+(max-value)/(max-min)*(h-top-bottom),path=points.map((p,i)=>(i?'L':'M')+x(p.date).toFixed(2)+','+y(p.value).toFixed(2)).join(' ');
 const grid=Array.from({length:5},(_,i)=>min+(max-min)*i/4).map(v=>`<line x1="${left}" x2="${w-right}" y1="${y(v).toFixed(2)}" y2="${y(v).toFixed(2)}" class="mc-grid"/><text x="${left-9}" y="${(y(v)+4).toFixed(2)}" text-anchor="end" class="mc-svg-label">${mcFormat(v)}</text>`).join('');
 const indices=[...new Set([0,Math.floor((points.length-1)/2),points.length-1])],ticks=indices.map(i=>`<text x="${x(points[i].date).toFixed(2)}" y="${h-20}" text-anchor="${i===0?'start':i===points.length-1?'end':'middle'}" class="mc-svg-label">${points[i].date}</text>`).join(''),dots=points.map(p=>{const tip=`${p.date}｜${q.label||q.symbol}｜${mcFormat(p.value)} ${unit}`;return `<circle cx="${x(p.date).toFixed(2)}" cy="${y(p.value).toFixed(2)}" r="4" class="mc-line-point" tabindex="0" data-chart-tip="${mcEscape(tip)}" aria-label="${mcEscape(tip)}" role="img"><title>${mcEscape(tip)}</title></circle>`}).join('');
 return `<figure class="mc-figure mc-price-figure"><figcaption>${mcEscape(q.label||q.symbol)} · ${mcEscape(unit)} · ${points[0].date} 至 ${points.at(-1).date}</figcaption><div class="mc-tooltip" role="status" aria-live="polite">滑過或聚焦圓點查看日期與數值；縱軸依數據範圍縮放，非零起點。</div><div class="mc-svg-scroll" tabindex="0" aria-label="歷史價格線圖，可橫向捲動"><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="${mcEscape(q.label||q.symbol)}歷史數據線圖，單位${mcEscape(unit)}"><title>歷史收盤值；非分時或即時報價</title>${grid}<path d="${path}" class="mc-price-line"/>${dots}${ticks}<text x="${left}" y="15" class="mc-svg-label">${mcEscape(unit)}</text></svg></div><p class="mc-chart-note">線段僅連接來源提供的收盤日期。缺少的交易日未補值，週末或休市期間也不填假報價。</p>${mcDisclosure(table)}</figure>`;
}
function marketComparisonChart(quotes){const rows=(Array.isArray(quotes)?quotes:[]).filter(q=>mcNumber(q.change_percent)!==null&&mcNumber(q.price)!==null).map(q=>({label:String(q.label||q.symbol),value:q.change_percent}));return signedHorizontalChart(rows,{unit:'%',title:'來源公布的日漲跌幅比較',caption:'只比較來源公布的日漲跌百分比；不同市場收盤時點可能不同，請核對下表日期。原幣價格不混用。'})}
function marketQuoteTable(quotes){return mcTable(['標的','市場／類型','價格／點位','日漲跌幅','資料日期','狀態／來源'],quotes.map(q=>[q.label||q.symbol,[q.market,q.kind].filter(Boolean).join(' / '),mcNumber(q.price)===null?'—':mcFormat(q.price)+' '+(q.unit==='index_points'?'指數點':q.currency||''),mcSigned(q.change_percent,'%'),q.as_of||'未提供',[marketStatus(q),q.source,q.delay,q.stale?'資料可能過時':'',marketErrorText(q.error)].filter(Boolean).join(' · ')]),'市場報價與日期核對表')}
function wsMarkets(){
 const visible=marketVisibleQuotes(),selected=visible.find(q=>q.id===marketSelected)||visible[0]||null;if(selected)marketSelected=String(selected.id||selected.symbol||'');
 const demo=typeof demoMode!=='undefined'&&demoMode||marketData?.demo;
 return wsHeader('讓市場資訊，有清楚的座標。','STOCK MARKET WORKSPACE','報價、日期、來源與可用狀態，一起看。',`<button class="btn primary" id="refreshMarkets" ${marketBusy?'disabled':''}>${marketBusy?'正在更新…':'更新市場資料'}</button>`)+`<div class="mc-status ${marketError?'mc-error':''}" role="${marketError?'alert':'status'}">${demo?'合成市場資料體驗：所有示例報價與歷史均為固定合成數字，不代表真實股市。':marketBusy?'正在向資料來源更新，尚未完成。':marketData?'顯示最近一次取得的資料；每筆報價各有日期、幣別與來源。':'尚未取得市場資料。進入此頁後會嘗試讀取本機後端。'}${marketError?'<br>'+mcEscape(marketError)+(marketData?'；保留上次取得的資料，未將失敗當成更新成功。':''):''}<br>來源限制：每輪最多6筆美股，每個來源更新後有60秒冷卻。可以選取單一標的再更新歷史；來源拒絕時保留原因。</div><div class="mc-market-filter"><label for="marketKind">市場與標的</label><select id="marketKind"><option value="all" ${marketFilter==='all'?'selected':''}>全部</option><option value="TW" ${marketFilter==='TW'?'selected':''}>台灣市場</option><option value="US" ${marketFilter==='US'?'selected':''}>美國市場</option><option value="etf" ${marketFilter==='etf'?'selected':''}>ETF</option><option value="index" ${marketFilter==='index'?'selected':''}>指數</option><option value="stock" ${marketFilter==='stock'?'selected':''}>個別股票</option></select><span class="mc-source-label">${visible.length} 筆標的 · 缺值顯示 —</span></div><div class="mc-quote-grid">${visible.map(q=>`<button class="mc-quote ${selected?.id===q.id?'selected':''}" data-market-select="${mcEscape(q.id||q.symbol)}" aria-pressed="${selected?.id===q.id?'true':'false'}"><span class="ws-kicker">${mcEscape(q.market||'—')} / ${mcEscape(q.symbol||q.kind||'—')}</span><strong>${mcEscape(q.label||q.symbol||'未命名標的')}</strong><span class="mc-quote-price">${mcFormat(q.price)} <small>${mcEscape(q.unit==='index_points'?'指數點':q.currency||'—')}</small></span><span class="mc-quote-change ${mcNumber(q.change_percent)<0?'down':'up'}">${mcSigned(q.change_percent,'%')} · ${mcEscape(marketStatus(q))}</span><span class="mc-quote-meta">${mcEscape(q.as_of||'尚無資料日期')}<br>${mcEscape(q.source||'尚無來源')}${q.delay?' · '+mcEscape(q.delay):''}${q.error?'<br>'+mcEscape(marketErrorText(q.error)):''}</span></button>`).join('')||'<div class="mc-empty"><strong>這個範圍目前沒有資料。</strong><p>可以切回全部標的，或更新資料；不會用零元假裝報價。</p></div>'}</div><section class="ws-card"><div class="mc-section-heading"><div><span class="ws-kicker">PRICE HISTORY / 收盤資料</span><h2>${mcEscape(selected?.label||'標的歷史走勢')}</h2></div><div class="mc-select-field"><label for="marketSymbol">選擇走勢標的</label><select id="marketSymbol" ${visible.length?'':'disabled'}>${visible.map(q=>`<option value="${mcEscape(q.id||q.symbol)}" ${selected?.id===q.id?'selected':''}>${mcEscape(q.label||q.symbol)}</option>`).join('')||'<option>尚無標的</option>'}</select><button class="btn" id="refreshMarketSelected" ${marketBusy||!selected?'disabled':''}>更新此標的與歷史</button></div></div>${marketPriceChart(selected)}</section><div class="mc-stat-grid"><section class="ws-card"><h2>日漲跌幅，一起看。</h2>${marketComparisonChart(visible)}</section><section class="ws-card"><h2>觀察標的，不冒充產業指數。</h2><p class="mc-chart-note">下方僅列個別股票的日漲跌幅。即使標示產業，也不代表整個產業的加權報酬、資金流或廣度。</p>${marketComparisonChart(visible.filter(q=>q.kind==='stock'))}</section></div><section class="ws-card"><h2>來源與數字核對</h2>${marketQuoteTable(visible)}<p class="mc-chart-note">部分資料來源需有效服務 Key 或額外權限；缺少授權、休市、延遲與舊資料會分別保留狀態。市場圖表不會自動改寫你的持倉估值，也不執行任何買賣。</p></section>`;
}
async function loadMarkets(refresh=false,options={}){
 if(marketBusy)return false;const generation=++marketGeneration;marketBusy=true;marketAttempted=true;marketError='';if(typeof page!=='undefined'&&page==='markets')draw();
 try{const result=typeof demoMode!=='undefined'&&demoMode?marketSyntheticData():await api(refresh?'/api/markets/refresh':'/api/markets',refresh?options:undefined);if(generation!==marketGeneration)return false;if(!result||!Array.isArray(result.quotes))throw Error('市場資料格式不完整；原有資料未覆寫。');marketData=result;marketError=marketErrorText(result.refresh_error);return !marketError}catch(error){if(generation===marketGeneration)marketError=String(error.message||'市場資料讀取失敗，請重試。');return false}finally{if(generation===marketGeneration){marketBusy=false;if(typeof page!=='undefined'&&page==='markets')draw()}}
}
function bindMarkets(){
 const root=typeof appRoot!=='undefined'?appRoot:document;
 root.querySelectorAll('[data-chart-tip]').forEach(point=>{const reveal=()=>{const figure=point.closest('figure'),tip=figure?.querySelector('.mc-tooltip');if(tip)tip.textContent=point.dataset.chartTip};point.addEventListener('pointerenter',reveal);point.addEventListener('focus',reveal)});
 if(typeof page==='undefined'||page!=='markets')return;
 const refresh=root.querySelector('#refreshMarkets');if(refresh)refresh.onclick=()=>loadMarkets(true);
 const selectedRefresh=root.querySelector('#refreshMarketSelected');if(selectedRefresh)selectedRefresh.onclick=()=>{if(!marketSelected)return false;return loadMarkets(true,{symbols:[marketSelected],history:true})};
 const kind=root.querySelector('#marketKind');if(kind)kind.onchange=()=>{marketFilter=kind.value;marketSelected='';draw()};
 const symbol=root.querySelector('#marketSymbol');if(symbol)symbol.onchange=()=>{marketSelected=symbol.value;draw()};
 root.querySelectorAll('[data-market-select]').forEach(button=>button.onclick=()=>{marketSelected=button.dataset.marketSelect;draw()});
 if(!marketAttempted&&!marketBusy)loadMarkets(false);
}
